.cs-rich-toolbar {
  display: flex;
  gap: 8px;
  padding: 8px 10px;
  margin: 6px 0;
  border-radius: 10px;
  background: linear-gradient(120deg, rgba(79, 70, 229, 0.09), rgba(59, 130, 246, 0.14));
  border: 1px dashed rgba(59, 130, 246, 0.6);
  align-items: center;
  flex-wrap: wrap;
}
.cs-rich-toolbar button {
  background: var(--bg-elevated, #0b1224);
  color: var(--text, #e2e8f0);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  padding: 6px 10px;
  font-size: 0.85rem;
  cursor: pointer;
  transition: transform 120ms ease, border-color 120ms ease;
}
.cs-rich-toolbar button:hover {
  transform: translateY(-1px) scale(1.01);
  border-color: rgba(59, 130, 246, 0.7);
}
.cs-rich-toolbar .cs-hotkey {
  opacity: 0.7;
  font-size: 0.75rem;
  margin-left: 4px;
}
.cs-rich-toolbar .cs-divider {
  width: 1px;
  height: 22px;
  background: rgba(255, 255, 255, 0.18);
  margin: 0 4px;
}
.cs-rich-toolbar[data-floating='true'] {
  position: sticky;
  top: 0;
  z-index: 10;
}
.cs-rich-toolbar .cs-tooltip {
  font-size: 0.75rem;
  color: var(--text-secondary, #cbd5e1);
}

