(function() {
  'use strict';
  if (window.__CS_RICH_TEXT_BOOST__) return;
  window.__CS_RICH_TEXT_BOOST__ = true;

  const api = window.CardSpoke?.utils;
  const selectors = ['.card-editor textarea', '.card-detail textarea', '.card-body textarea', '.card-detail-body textarea', 'textarea.markdown-editor'];

  const wrapText = (el, wrapper) => {
    if (!el) return;
    const { selectionStart, selectionEnd, value } = el;
    const hasSelection = selectionStart !== undefined && selectionEnd !== undefined && selectionEnd > selectionStart;
    const selected = hasSelection ? value.slice(selectionStart, selectionEnd) : '';
    const insertion = wrapper(selected || 'text');
    const before = value.slice(0, selectionStart || 0);
    const after = value.slice(selectionEnd || value.length);
    el.value = `${before}${insertion}${after}`;
    const cursor = (selectionStart || 0) + insertion.length;
    el.focus();
    el.setSelectionRange(cursor, cursor);
    el.dispatchEvent(new Event('input', { bubbles: true }));
  };

  const commands = [
    { label: 'Bold', hotkey: 'Ctrl/Cmd+B', action: (el) => wrapText(el, (t) => `**${t}**`) },
    { label: 'Italic', hotkey: 'Ctrl/Cmd+I', action: (el) => wrapText(el, (t) => `*${t}*`) },
    { label: 'Underline', hotkey: 'Ctrl/Cmd+U', action: (el) => wrapText(el, (t) => `__${t}__`) },
    { label: 'Highlight', hotkey: 'Ctrl/Cmd+H', action: (el) => wrapText(el, (t) => `==${t}==`) },
    { label: 'Inline Code', hotkey: 'Ctrl/Cmd+`', action: (el) => wrapText(el, (t) => `\`${t}\``) },
    { label: 'Quote', hotkey: 'Ctrl/Cmd+Q', action: (el) => wrapText(el, (t) => `> ${t}`) },
    { label: 'Divider', hotkey: '---', action: (el) => wrapText(el, () => `

---

`) },
  ];

  const shortcutHandler = (event) => {
    const active = document.activeElement;
    if (!active || active.tagName !== 'TEXTAREA') return;
    const mod = event.metaKey || event.ctrlKey;
    if (!mod) return;
    const keyMap = {
      b: 0,
      i: 1,
      u: 2,
      h: 3,
      '`': 4,
      q: 5,
    };
    const index = keyMap[event.key];
    if (index !== undefined) {
      event.preventDefault();
      commands[index].action(active);
    }
  };

  const buildToolbar = (target) => {
    if (!target || target.parentElement?.querySelector('.cs-rich-toolbar')) return;
    const bar = document.createElement('div');
    bar.className = 'cs-rich-toolbar';
    bar.dataset.floating = 'true';

    commands.forEach((cmd, idx) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.textContent = cmd.label;

      const span = document.createElement('span');
      span.className = 'cs-hotkey';
      span.textContent = cmd.hotkey;
      btn.appendChild(span);

      btn.addEventListener('click', (e) => {
        e.preventDefault();
        cmd.action(target);
      });

      bar.appendChild(btn);
      if (idx === 2 || idx === 4) {
        const divider = document.createElement('span');
        divider.className = 'cs-divider';
        bar.appendChild(divider);
      }
    });

    const tip = document.createElement('span');
    tip.className = 'cs-tooltip';
    tip.textContent = 'Rich Text Boost • Markdown friendly';
    bar.appendChild(tip);

    target.parentElement?.insertBefore(bar, target);
  };

  const scanEditors = () => {
    selectors.forEach((selector) => {
      document.querySelectorAll(selector).forEach(buildToolbar);
    });
  };

  document.addEventListener('keydown', shortcutHandler);
  const observer = new MutationObserver(() => setTimeout(scanEditors, 50));
  observer.observe(document.body, { childList: true, subtree: true });
  scanEditors();

  api?.showToast('Rich Text Boost loaded with formatting shortcuts', 'success');
})();
